create table users (
 id bigint generated by default as identity primary key, username varchar(100) not null unique, password_hash varchar(255), email varchar(254) unique, role varchar(20) not null, authentication_type varchar(20) not null, enabled boolean not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null
);
create table customers (
 id bigint generated by default as identity primary key, customer_id varchar(20) not null unique, name varchar(150) not null, phone varchar(30) not null, email varchar(254), user_id bigint unique, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint fk_customers_user foreign key (user_id) references users(id)
);
create table employees (
 id bigint generated by default as identity primary key, employee_id varchar(20) not null unique, name varchar(150) not null, phone varchar(30) not null, email varchar(254), user_id bigint unique, role varchar(20) not null, active boolean not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint fk_employees_user foreign key (user_id) references users(id)
);
create table vehicles (
 id bigint generated by default as identity primary key, vehicle_id varchar(20) not null unique, customer_id bigint not null, make varchar(80) not null, model varchar(80) not null, model_year integer, color varchar(50) not null, license_plate varchar(30) not null unique, vin varchar(50), current_mileage bigint, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint fk_vehicles_customer foreign key (customer_id) references customers(id)
);
create table appointments (
 id bigint generated by default as identity primary key, appointment_id varchar(20) not null unique, customer_id bigint not null, vehicle_id bigint not null, requested_date date not null, requested_time time not null, service_type varchar(30) not null, issue_description text, priority varchar(10), status varchar(20) not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint fk_appointments_customer foreign key (customer_id) references customers(id), constraint fk_appointments_vehicle foreign key (vehicle_id) references vehicles(id)
);
create table service_cases (
 id bigint generated by default as identity primary key, service_case_id varchar(30) not null unique, customer_id bigint not null, vehicle_id bigint not null, appointment_id bigint unique, visit_type varchar(20) not null, service_type varchar(30) not null, priority varchar(10) not null, status varchar(30) not null, check_in_time timestamp with time zone, diagnosis text, solution text, technician_notes text, created_by_employee_id bigint, assigned_employee_id bigint, ready_for_pickup_at timestamp with time zone, delivered_at timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint fk_cases_customer foreign key (customer_id) references customers(id), constraint fk_cases_vehicle foreign key (vehicle_id) references vehicles(id), constraint fk_cases_appointment foreign key (appointment_id) references appointments(id), constraint fk_cases_creator foreign key (created_by_employee_id) references employees(id), constraint fk_cases_assignee foreign key (assigned_employee_id) references employees(id)
);
create table service_issues (id bigint generated by default as identity primary key, service_case_id bigint not null, issue_description text not null, additional_notes text, reported_at timestamp with time zone not null, reported_by varchar(100), constraint fk_issues_case foreign key (service_case_id) references service_cases(id));
create table diagnoses (id bigint generated by default as identity primary key, service_case_id bigint not null, diagnosis text not null, technician_notes text, diagnosed_by_employee_id bigint, diagnosed_at timestamp with time zone not null, constraint fk_diagnoses_case foreign key (service_case_id) references service_cases(id), constraint fk_diagnoses_employee foreign key (diagnosed_by_employee_id) references employees(id));
create table service_items (id bigint generated by default as identity primary key, service_case_id bigint not null, name varchar(150) not null, description text, quantity integer not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint fk_items_case foreign key (service_case_id) references service_cases(id));
create table notifications (id bigint generated by default as identity primary key, notification_id varchar(20) not null unique, customer_id bigint not null, service_case_id bigint, title varchar(200) not null, message text not null, type varchar(30) not null, is_read boolean not null, created_at timestamp with time zone not null, read_at timestamp with time zone, constraint fk_notifications_customer foreign key (customer_id) references customers(id), constraint fk_notifications_case foreign key (service_case_id) references service_cases(id));

create index idx_users_username on users(username); create index idx_customers_customer_id on customers(customer_id); create index idx_employees_employee_id on employees(employee_id); create index idx_vehicles_vehicle_id on vehicles(vehicle_id); create index idx_vehicles_license_plate on vehicles(license_plate); create index idx_appointments_appointment_id on appointments(appointment_id); create index idx_appointments_status on appointments(status); create index idx_service_cases_service_case_id on service_cases(service_case_id); create index idx_service_cases_status on service_cases(status); create index idx_service_cases_priority on service_cases(priority); create index idx_notifications_notification_id on notifications(notification_id);
